<template><div class="assistant-results"><template v-for="action in actions" :key="action.id || action.type"><section v-if="['search_houses','get_house_detail'].includes(action.type)" class="house-results"><div class="result-heading"><strong>为你找到的房源</strong><span>共 {{ action.result?.total ?? action.result?.list?.length ?? 0 }} 套 · 展示 {{ action.result?.list?.length || 0 }} 套 · 点击图片快速查看</span></div><p v-if="!action.result?.list?.length" class="empty-result">暂时没有匹配房源，可以调整区域或预算。</p><div class="assistant-house-grid"><article v-for="house in action.result?.list || []" :key="house.id || house.houseId" class="assistant-house"><button class="house-picture" @click="quickView(house.id||house.houseId)" :aria-label="'快速查看'+house.title"><img :src="house.coverImage || fallback" :alt="house.title" @error="imageFallback" /><span>快速查看 ↗</span></button><div class="house-copy"><RouterLink :to="'/detail/'+(house.id||house.houseId)">{{ house.title }}</RouterLink><p>{{ house.city }} · {{ house.district }}<template v-if="house.bedrooms"> · {{ house.bedrooms }}室</template><template v-if="house.area"> · {{ house.area }}㎡</template></p><div><strong>¥{{ Number(house.price||0).toLocaleString('zh-CN') }}<small>/月</small></strong><RouterLink :to="'/detail/'+(house.id||house.houseId)">详情 →</RouterLink></div></div></article></div></section>
 <section v-else-if="action.type==='policy_qa'" class="knowledge-result"><details open><summary>查到的依据与来源 <span>{{ action.result?.sources?.length || 0 }} 条</span></summary><p v-if="!action.result?.sources?.length">现有资料不足，请补充问题或咨询专业人士。</p><details v-for="(source,i) in action.result?.sources||[]" :key="i" class="source-item"><summary>资料{{ i+1 }} · {{ source.docTitle || '知识库资料' }}</summary><p>{{ source.text }}</p></details></details></section>
 <section v-else-if="action.type==='contract_review'" class="contract-result"><h3>合同审查结果 <span>{{ riskLabel(action.result?.overallRisk) }}</span></h3><p v-if="action.result?.summary">{{ action.result.summary }}</p><details v-for="(risk,i) in action.result?.riskPoints || action.result?.risks || []" :key="i" open><summary>{{ typeof risk==='string'?risk:(risk.point || risk.title || risk.clauseText || '需要留意的条款') }}</summary><p>{{ risk.reason || risk.riskDescription || risk.explanation || risk.suggestion || risk.description }}</p><p v-if="risk.suggestion && (risk.reason||risk.riskDescription)">建议：{{ risk.suggestion }}</p><p v-if="risk.law" class="risk-source">依据：{{ risk.law }}</p><p v-if="risk.source" class="risk-source">来源：{{ risk.source }}</p><div v-for="(source,si) in risk.sources||[]" :key="si" class="risk-source">{{ source.docTitle || source.title }}：{{ source.text || source.content }}</div></details><details v-if="action.result?.keyClauses?.length"><summary>查看条款明细</summary><div v-for="(clause,i) in action.result.keyClauses" :key="i"><strong>{{ clause.clause }}</strong><p>{{ clause.content }}</p></div></details></section>
 <section v-else-if="action.type==='calculate_cost'" class="cost-result"><h3>费用明细</h3><template v-for="(block,key) in action.result || {}" :key="key"><div v-if="block && typeof block==='object'"><h4>{{ costHeading(key) }}</h4><dl><template v-for="(value,label) in block" :key="label"><dt>{{ costLabel(label) }}</dt><dd>{{ typeof value==='number'?'¥ '+value.toLocaleString('zh-CN'):value }}</dd></template></dl></div></template></section>
 </template><dialog ref="dialog" class="house-dialog" @click="dialogBackdrop"><button class="dialog-close" aria-label="关闭房源快速查看" @click="dialog.close()">×</button><p v-if="detailLoading">正在加载房源…</p><p v-else-if="detailError" role="alert">{{ detailError }}</p><template v-else-if="detail"><img class="dialog-photo" :src="detail.coverImage || fallback" :alt="detail.title" @error="imageFallback" /><div class="dialog-copy"><span>{{ detail.city }} · {{ detail.district }}</span><h2>{{ detail.title }}</h2><strong>¥{{ Number(detail.price).toLocaleString('zh-CN') }} /月</strong><p>{{ detail.bedrooms }}室{{ detail.livingRooms }}厅 · {{ detail.area }}㎡ · {{ detail.orientation || '朝向待了解' }}</p><p>{{ detail.address }}</p><p class="dialog-description">{{ detail.description }}</p><div><RouterLink :to="'/detail/'+detail.id" @click="dialog.close()">打开完整详情 ↗</RouterLink><button @click="askHouse">让小易分析这套房</button></div></div></template></dialog></div></template>
<script setup>
import {ref} from 'vue'
import {houseApi} from '../api/house'
defineProps({actions:{type:Array,default:()=>[]}});const emit=defineEmits(['ask']),dialog=ref(null),detail=ref(null),detailLoading=ref(false),detailError=ref(''),fallback='/house-images/uns_1600210492486-724fe5c67fb0.jpg';let requestVersion=0
function imageFallback(event){if(!event.target.src.endsWith(fallback))event.target.src=fallback}
async function quickView(id){const version=++requestVersion;detail.value=null;detailError.value='';detailLoading.value=true;dialog.value.showModal();try{const r=await houseApi.detail(id);if(version===requestVersion)detail.value=r.data}catch(e){if(version===requestVersion)detailError.value=e.message||'房源暂时无法加载'}finally{if(version===requestVersion)detailLoading.value=false}}
function dialogBackdrop(event){if(event.target!==dialog.value)return;const r=dialog.value.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.value.close()}
function askHouse(){emit('ask',`请帮我分析房源ID ${detail.value.id} 是否值得租，说明优点、需要核实的地方和费用。`);dialog.value.close()}
const riskLabel=v=>({HIGH:'风险较高',MEDIUM:'有条款需留意',LOW:'风险较低'}[v]||'请核对条款')
const costHeading=k=>({initialCost:'首次入住准备',monthlyCost:'每月支出'}[k]||k)
const costLabel=k=>({firstMonthRent:'首月租金',deposit:'押金',agentFeeRange:'中介费参考',minTotal:'最低准备金额',rent:'房租',utilityEstimate:'水电燃气参考',internetEstimate:'网费参考',total:'每月合计',propertyFee:'物业费参考'}[k]||k)
</script>
<style scoped>
.assistant-results{margin-top:16px}.result-heading{display:flex;justify-content:space-between;gap:15px;align-items:center;margin:0 0 12px}.result-heading strong{font-size:13px;font-weight:600}.result-heading>span{font-size:10px;color:var(--jade-muted)}.assistant-house-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.assistant-house{min-width:0;background:#fffefa;border:1px solid var(--jade-line);border-radius:7px;overflow:hidden}.house-picture{display:block;width:100%;aspect-ratio:1.7;border:0;padding:0;position:relative;overflow:hidden;background:#e6ebe2;cursor:pointer}.house-picture img{width:100%;height:100%;object-fit:cover;transition:transform .5s}.house-picture:hover img{transform:scale(1.04)}.house-picture span{position:absolute;right:10px;bottom:10px;background:#143b31b3;color:white;font-size:10px;padding:5px 9px;border-radius:3px}.house-copy{padding:14px}.house-copy>a{font-size:13px;color:var(--jade-900);line-height:1.7;display:block;font-weight:500}.house-copy>p{font-size:10px;color:var(--jade-muted);margin:7px 0 12px}.house-copy>div{display:flex;align-items:center;justify-content:space-between}.house-copy strong{font-size:19px;color:var(--jade-700)}.house-copy strong small{font-size:10px;font-weight:400;margin-left:3px}.house-copy>div>a{font-size:10px;color:var(--jade-700)}.knowledge-result,.contract-result,.cost-result{padding:18px;background:#f3f6ed;border:1px solid #dbe3d5;border-radius:7px;margin-top:15px;font-size:12px;line-height:1.9}.knowledge-result summary,.contract-result summary{cursor:pointer}.knowledge-result>details>summary{font-weight:600}.knowledge-result summary span{font-weight:400;font-size:10px;color:var(--jade-muted);margin-left:7px}.source-item{padding-top:10px;margin-top:10px;border-top:1px solid #dbe3d5}.source-item p{font-size:11px;color:#6c7d69;white-space:pre-wrap;max-height:220px;overflow:auto}.contract-result h3,.cost-result h3{font-size:14px;margin:0 0 13px}.contract-result h3 span{font-size:10px;margin-left:15px;color:#977447}.contract-result details{padding:10px 0;border-top:1px solid #dbe3d5}.contract-result p{font-size:12px;margin:8px 0}.risk-source{font-size:10px;color:#6d7a66}.cost-result h4{margin:12px 0 8px;font-weight:500}.cost-result dl{display:grid;grid-template-columns:1fr auto;gap:6px;font-size:12px}.cost-result dd{margin:0}.house-dialog{width:min(900px,calc(100vw - 40px));max-height:85svh;overflow:auto;border:0;border-radius:9px;padding:0;box-shadow:0 30px 90px #103d3659;background:#fffefa;color:var(--jade-ink);margin:auto}.house-dialog::backdrop{background:#143b3170;backdrop-filter:blur(4px)}.dialog-close{position:absolute;right:15px;top:15px;width:32px;height:32px;border:0;border-radius:50%;background:#fffefaeb;color:var(--jade-900);font-size:23px;cursor:pointer;z-index:1}.dialog-photo{width:100%;height:300px;object-fit:cover}.dialog-copy{padding:26px 32px}.dialog-copy>span{font-size:11px;color:var(--jade-muted)}.dialog-copy h2{font-family:var(--font-display);font-size:25px;font-weight:500;line-height:1.6;margin:12px 0}.dialog-copy>strong{font-size:25px;color:var(--jade-700)}.dialog-copy p{font-size:12px;line-height:1.9;margin:12px 0}.dialog-description{white-space:pre-wrap;max-height:180px;overflow:auto;color:#73806b}.dialog-copy>div{display:flex;gap:20px;align-items:center;margin-top:20px}.dialog-copy a,.dialog-copy button{font-size:12px;color:var(--jade-700)}.dialog-copy button{background:#e9f2e5;border:1px solid #cddcc9;border-radius:4px;padding:9px 13px;cursor:pointer}.empty-result{font-size:12px;color:var(--jade-muted)}@media(max-width:600px){.assistant-house-grid{grid-template-columns:1fr}.result-heading{align-items:flex-start;flex-direction:column;gap:5px}.dialog-copy{padding:20px}.dialog-photo{height:230px}}
</style>
